<template>
<section class="tracking"><header><h2>事件跟踪</h2><el-button type="primary" @click="createOpen=true">发起事项</el-button></header>
<el-alert v-if="error" :title="error" type="error" show-icon />
<el-tabs v-model="view" @tab-change="reload"><el-tab-pane v-for="(label,key) in visibleViews" :key="key" :label="label" :name="key" /></el-tabs>
<div class="filters"><el-input v-model="search" placeholder="标题、内容或单据号" clearable @keyup.enter="reload"/><el-select v-model="status" placeholder="未关闭事项" clearable><el-option v-for="(label,key) in states" :key="key" :label="label" :value="key"/></el-select><el-select v-model="department" clearable placeholder="归属部门"><el-option v-for="d in candidates.departments" :key="d.id" :label="d.name" :value="d.id"/></el-select><el-select v-model="assignee" clearable filterable placeholder="主处理人"><el-option v-for="u in candidates.users" :key="u.id" :label="u.full_name||u.username" :value="u.id"/></el-select><el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="发起日期从" end-placeholder="至"/><el-checkbox v-if="status==='closed'" v-model="allHistory">全部关闭历史</el-checkbox><el-checkbox v-model="overdue">仅逾期</el-checkbox><el-button @click="reload">查询</el-button></div>
<el-table :data="paged" v-loading="busy" @row-click="open"><el-table-column prop="title" label="事项" min-width="200"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]}} <el-tag v-if="row.overdue_recorded||row.is_overdue" type="danger">曾逾期</el-tag></template></el-table-column><el-table-column label="处理人"><template #default="{row}">{{userName(row.assignee)}}</template></el-table-column><el-table-column label="归属部门"><template #default="{row}">{{deptName(row.department)}}</template></el-table-column><el-table-column label="要求完成时间（北京时间）" min-width="180"><template #default="{row}">{{trackingTime(row.due_at)}}</template></el-table-column><el-table-column prop="record_number" label="关联单据"/></el-table>
<el-pagination v-model:current-page="page" :page-size="20" :total="total" @current-change="reload(false)" layout="total, prev, pager, next"/>
<el-collapse><el-collapse-item title="站内通知"><el-empty v-if="!notifications.length" description="暂无通知"/><p v-for="n in notifications" :key="n.id"><el-button link @click="openNotification(n)">事项 #{{n.issue}} · {{actions[n.action]||eventLabels[n.action]||n.action}} · {{trackingTime(n.created_at)}} {{n.read_at?'':'（未读）'}}</el-button></p></el-collapse-item></el-collapse>
<el-drawer v-model="detailOpen" title="事项详情" size="min(720px, 95vw)"><template v-if="detail"><h3>{{detail.title}}</h3><p>{{detail.description}}</p><p>{{states[detail.status]}} · {{deptName(detail.department)}} · 处理人：{{userName(detail.assignee)}}</p><p>发起人：{{userName(detail.creator)}} · {{trackingTime(detail.created_at)}}</p><p>要求完成：{{trackingTime(detail.due_at)}}</p><p v-if="detail.submitted_at">提交完成：{{trackingTime(detail.submitted_at)}}</p><p v-if="detail.last_reminded_at">最近催办：{{trackingTime(detail.last_reminded_at)}}</p><p v-if="detail.status==='closed'">关闭时间：{{trackingTime(detail.closed_at)}} · 关闭原因：{{closeLabels[detail.close_reason]||detail.close_reason}}</p><p>首次反馈：{{detail.first_feedback_at?trackingTime(detail.first_feedback_at):'尚未反馈'}} · 最近反馈：{{detail.last_feedback_at?trackingTime(detail.last_feedback_at):'尚未反馈'}}</p><p v-if="detail.status==='confirming'">等待确认：{{Math.floor((detail.confirmation_wait_seconds||0)/3600)}} 小时</p><p v-if="detail.page_path">关联页面：<router-link :to="businessLink(detail)">{{detail.record_number||detail.page_path}}</router-link></p>
<div class="filters"><el-select v-model="operation" placeholder="选择操作"><el-option v-for="a in detail.permissions" :key="a" :label="actions[a]" :value="a"/></el-select><el-select v-if="operation==='reassign'" v-model="targetUser" filterable placeholder="新处理人"><el-option v-for="u in detailCandidates.users" :key="u.id" :value="u.id" :label="u.full_name||u.username"/></el-select><el-select v-if="operation==='transfer'" v-model="targetDepartment" placeholder="接收部门"><el-option v-for="d in candidates.departments" :key="d.id" :value="d.id" :label="d.name"/></el-select><el-date-picker v-if="operation==='reschedule'" v-model="targetDate" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="新的截止时间"/><el-select v-if="operation==='close'" v-model="closeReason"><el-option label="已完成" value="completed"/><el-option label="已取消" value="cancelled"/><el-option label="无需继续" value="unnecessary"/></el-select></div><el-input v-model="content" type="textarea" placeholder="办理进展、处理结果或操作原因"/><el-button :disabled="!operation" :loading="saving" type="primary" @click="act">{{actions[operation]||'执行操作'}}</el-button>
<label v-if="detail.status!=='closed' && detail.permissions.includes('feedback')">补充附件 <input type="file" @change="upload"/></label><p v-for="a in detail.attachments" :key="a.id"><el-button link @click="download(a)">{{a.name}}</el-button></p>
<el-timeline><el-timeline-item v-for="e in detail.events" :key="e.id" :timestamp="trackingTime(e.created_at)">{{actions[e.action]||eventLabels[e.action]||e.action}} · {{userName(e.actor)}}<p>{{e.content}}</p><p v-if="e.data?.before && ['reassign','reschedule','transfer'].includes(e.action)">{{changeText(e)}}</p></el-timeline-item></el-timeline></template></el-drawer>
<el-drawer v-model="createOpen" title="发起跟踪事项" size="min(700px, 95vw)"><IssueForm v-if="createOpen" :context="context" :candidates="candidates" @created="created"/></el-drawer>
</section>
</template>
<script setup>
import { computed, ref, onMounted, watch } from 'vue';
import { useRoute } from 'vue-router';
import { ElMessage } from 'element-plus';
import axios from 'axios';
import { getAccessToken } from '../../utils/authSession';
import { apiBaseUrl } from '../../api/baseUrl';
import { tracking, rows, states, actions } from '../../api/issueTracking';
import { trackingTime, eventLabels } from '../../components/issueTracking/display';
import { dateFilters } from '../../components/issueTracking/filters';
import IssueForm from '../../components/issueTracking/IssueForm.vue';
const props=defineProps({context:{type:Object,default:()=>({})},initialIssueId:{type:[String,Number],default:''}});
const route=useRoute(), views={created:'我发起的',assigned:'我负责的',collaborating:'我协办的',managed:'管辖事项'};
const closeLabels={completed:'已完成',cancelled:'已取消',unnecessary:'无需继续'};
const allHistory=ref(false);
const department=ref(null),assignee=ref(null),dateRange=ref(null);
const view=ref('assigned'), search=ref(''), status=ref(''), overdue=ref(false), page=ref(1), items=ref([]), candidates=ref({users:[],departments:[]}), notifications=ref([]), busy=ref(false), error=ref(''), detail=ref(null), detailOpen=ref(false), createOpen=ref(false), operation=ref(''), content=ref(''), targetUser=ref(null), targetDepartment=ref(null), targetDate=ref(''), closeReason=ref('completed'),saving=ref(false);
const visibleViews=computed(()=>Object.fromEntries(Object.entries(views).filter(([key])=>key!=='managed'||candidates.value.can_manage)));
const detailCandidates=ref({users:[],departments:[]});
const total=ref(0);const paged=computed(()=>items.value);
function changeText(e){const b=e.data.before,a=e.data.after||{};if(e.action==='reassign')return `处理人：${userName(b.assignee)} → ${userName(a.assignee)}`;if(e.action==='transfer')return `归属部门：${deptName(b.department)} → ${deptName(a.department)}`;return `要求完成时间：${trackingTime(b.due_at)} → ${trackingTime(a.due_at)}`;}
function businessLink(item){if(item.record_type==='approval')return `/workflow/approvals/${item.record_id}`;if(item.record_type==='exception')return `/workflow/exceptions/${item.record_id}`;const queryKey={purchase_order:'order_id',supplier_shipment:'shipment_id',dispatch_batch:'batch_id',inbound_order:'inbound_id'}[item.record_type];return queryKey?{path:item.page_path,query:{[queryKey]:item.record_id}}:item.page_path;}
const userName=id=>candidates.value.users.find(u=>u.id===id)?.full_name||candidates.value.users.find(u=>u.id===id)?.username||`用户 #${id}`;
const deptName=id=>candidates.value.departments.find(d=>d.id===id)?.name||`部门 #${id}`;
async function reload(reset=true){if(reset!==false)page.value=1;busy.value=true;error.value='';try{const data=await tracking('issues/','get',null,{view:view.value,search:search.value,department:department.value,assignee:assignee.value,...dateFilters(dateRange.value,status.value,allHistory.value),status:status.value||'open',overdue:overdue.value?'true':'',page:page.value,page_size:20,...props.context});items.value=rows(data);total.value=data.count??items.value.length;notifications.value=rows(await tracking('notifications/'));}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function open(row){try{detail.value=await tracking(`issues/${row.id}/`);detailOpen.value=true;detailCandidates.value={users:[],departments:[]};try{detailCandidates.value=await tracking('candidates/','get',null,{menu_key:detail.value.menu_key||'',record_type:detail.value.record_type||'',record_id:detail.value.record_id||''});}catch{ /* Tracking visibility is independent of the linked business record. */ }operation.value='';content.value='';}catch(e){error.value=e.message;}}
async function act(){saving.value=true;try{await tracking(`issues/${detail.value.id}/actions/`,'post',{action:operation.value,content:content.value,assignee:targetUser.value,department:targetDepartment.value,due_at:targetDate.value,close_reason:closeReason.value});await open(detail.value);await reload();window.dispatchEvent(new Event('issue-tracking-updated'));ElMessage.success('操作已保存');}catch(e){error.value=e.message;ElMessage.error(e.message);}finally{saving.value=false;}}
async function upload(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;const data=new FormData();data.append('file',file);try{await tracking(`issues/${detail.value.id}/attachments/`,'post',data);await open(detail.value);}catch(e){error.value=e.message;}}
async function download(a){try{const r=await axios.get(`${apiBaseUrl}/api/internal/issue-tracking/attachments/${a.id}/download/`,{responseType:'blob',headers:{Authorization:`Bearer ${getAccessToken()}`}});const url=URL.createObjectURL(r.data),link=document.createElement('a');link.href=url;link.download=a.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{ElMessage.error('附件下载失败或权限已变更');}}
async function openNotification(n){await open({id:n.issue});await tracking('notifications/','post',{id:n.id});await reload();}
async function created(issue){window.dispatchEvent(new Event('issue-tracking-updated'));createOpen.value=false;await reload();await open(issue);}
watch(()=>props.initialIssueId,id=>{if(id)open({id});});
watch(()=>props.context,async()=>{try{candidates.value=await tracking('candidates/','get',null,{menu_key:props.context.menu_key||'',record_type:props.context.record_type||'',record_id:props.context.record_id||''});await reload();}catch(e){error.value=e.message;}},{deep:true});
onMounted(async()=>{try{candidates.value=await tracking('candidates/','get',null,{menu_key:props.context.menu_key||'',record_type:props.context.record_type||'',record_id:props.context.record_id||''});await reload();const issueId=props.initialIssueId||(!props.context.menu_key?route.query.issue:'');if(issueId)await open({id:issueId});}catch(e){error.value=e.message;}});
</script>
<style scoped>.tracking{padding:16px;background:white;border-radius:10px}header,.filters{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin-bottom:16px}header{justify-content:space-between}.filters .el-input{max-width:260px}.filters .el-select{width:180px}.el-pagination{margin:16px 0}.el-timeline{margin-top:24px}.el-button{margin-top:8px}</style>
